            privacyS3Intro: 'De behandeling is gebaseerd op:',
            privacyS3Li1: 'Kunst. 6(1)(a) AVG – vrijwillige toestemming van de gebruiker',
            privacyS3Li2: 'Kunst. 6(1)(f) AVG – legitiem belang (verstrekking van app-functionaliteiten)',
            privacyS4Title: '4. Locatie',
            privacyS4Intro: 'De app kan browsergeolocatie (GPS) gebruiken om:',
            privacyS4Li1: 'Toon producenten in de buurt',
            privacyS4Li2: 'Stel bereikcirkel in op de kaart',
            privacyS4Note: 'Locatiegegevens niet <strong>niet</strong> naar een server verzonden – ze worden alleen lokaal op het apparaat van de gebruiker verwerkt.',
            privacyS5Title: '5. Gebruikersrechten (AVG)',
            privacyS5Intro: 'In overeenstemming met de AVG heeft elke gebruiker de volgende rechten:',
