            privacyS5Li2: 'Recht op rectificatie (art. 16 AVG)',
            privacyS5Li3: 'Recht op verwijdering (“recht om vergeten te worden”) (art. 17 AVG)',
            privacyS5Li4: 'Recht op beperking van de verwerking (art. 18 AVG)',
