            privacyS5Contact: 'Om deze rechten uit te oefenen, kunt u contact opnemen met de verantwoordelijke persoon:<a href="mailto:krispolik6@gmail.com">krispolik6@gmail.com</a>',
            privacyS6Title: '6. Houdbaarheid',
            privacyS6Intro: 'Gegevens worden lokaal op het apparaat van de gebruiker opgeslagen tot een van de volgende gebeurtenissen. De gebruiker kan op elk gewenst moment alle gegevens verwijderen door de browseropslag te wissen.',
            privacyS6Li1: 'Handmatige verwijdering door gebruiker (browsergegevens wissen)',
            privacyS6Li2: 'De app verwijderen (PWA)',
            privacyS7Title: '7. Cookies en analyses',
            privacyS7Body: 'De app maakt geen gebruik van cookies voor gebruikerstracking of analysetools (bijvoorbeeld Google Analytics). Sommige diensten van derden (bijv. Leaflet, Font Awesome) kunnen cookies gebruiken – zie hun privacybeleid. Gegevens blijven lokaal op het apparaat; communicatie met externe diensten (kaart, lettertypen) maakt gebruik van HTTPS.',
            privacyS8Title: '8. Wijzigingen in dit beleid',
            privacyS8Body: 'Wij behouden ons het recht voor om dit privacybeleid te wijzigen. Gebruikers worden op de hoogte gesteld van wijzigingen door de datum bovenaan dit document bij te werken. De App is niet bedoeld voor personen jonger dan 13 jaar; wij verzamelen niet bewust gegevens van minderjarigen.'
