            termsS7Li4: 'správanie výrobcov voči používateľom',
            termsS7P3: '3. Používatelia a Výrobcovia používajú Platformu na vlastné riziko. Všetky transakcie a zmluvy sa uzatvárajú priamo medzi nimi.',
            termsS8Title: '§8 Zodpovednosť výrobcov za obsah',
            termsS8P1: '1. Za obsah zverejnený v Aplikácii (popis produktov, fotografie, ceny, kontaktné údaje) sú zodpovední výlučne výrobcovia.',
            termsS8P2: '2.Regionaler Geschmack neoveruje správnosť alebo zákonnosť obsahu zverejneného výrobcami.',
            termsS8P3: '3. Výrobcovia sa zaväzujú dodržiavať platné právne predpisy, vrátane predpisov o ochrane spotrebiteľa a potravín.',
