            termsS9P1: '1. Aplikácia využíva geografické údaje z OpenStreetMap (licencia ODbL). Presnosť závisí od komunity OpenStreetMap.',
            termsS9P2: '2.Regionaler Geschmack nezodpovedá za nepresnosti v geografických údajoch, umiestnení výrobcov alebo nesprávnych smeroch trasy.',
            termsS10Title: '§10 Ochrana osobných údajov',
            termsS10P1: '1. Prevádzkovateľ uplatňuje technické a organizačné opatrenia na ochranu osobných údajov pred stratou, zničením alebo neoprávneným prístupom.',
            termsS10P2: '2. Užívateľ má právo na prístup k svojim údajom, na ich opravu, vymazanie a na prenos.',
            termsS10P3: '3. Podrobnosti týkajúce sa ochrany osobných údajov nájdete v zásadách ochrany osobných údajov aplikácie.',
