            termsS1Body: 'Ovi uslovi reguliraju korištenje web aplikacije Regionaler Geschmack ("Aplikacija"). Korištenje aplikacije predstavlja prihvaćanje ovih uvjeta.',
            termsS2Title: '§2 Definicije',
            termsS2Body: '<strong>Korisnik</strong> –  osoba koja koristi aplikaciju. <strong>Proizvođač</strong> –  lokalni dobavljač hrane ili ugostiteljskih usluga. <strong>Dobavljač</strong> –  operater aplikacije Regionaler Geschmack.',
            termsS3Title: '§3 Pravila korištenja',
