            termsS4Title: '§4 Registracija',
            termsS4Body: 'Osnovne funkcije aplikacije dostupne su bez registracije. Izborna registracija računa za spremanje favorita i praćenje narudžbi bit će ponuđena u budućim izdanjima.',
            termsS5Title: '§5 Odgovornost',
            termsS5Body: 'Dobavljač nije odgovoran za sadržaj objavljen od strane proizvođača niti za kvalitetu proizvoda. Informacije u aplikaciji su indikativne – detalje potvrdite izravno s proizvođačem.',
            termsS6Title: '§6 Završne odredbe',
            termsS6Body: 'Dobavljač zadržava pravo izmjene ovih uvjeta. Trenutna verzija uvijek je dostupna u izborniku aplikacije. Neriješena pitanja regulirana su pravom Savezne Republike Njemačke.',
            termsS7Title: '§7 Odgovornost platforme',
            termsS7P1: '1.Regionaler Geschmack je platforma koja povezuje korisnike i proizvođače. Nije strana u transakciji između korisnika i proizvođača.',
            termsS7P2Intro: '2.Regionaler Geschmack nije odgovoran za:',
