            termsS8P3: '3. Proizvođači se obvezuju pridržavati se važećih zakona, uključujući propise o zaštiti potrošača i hrani.',
            termsS9Title: '§9 Odgovornost za geografske podatke',
            termsS9P1: '1. Aplikacija koristi geografske podatke iz OpenStreetMapa (ODbL licenca). Točnost ovisi o zajednici OpenStreetMap.',
            termsS9P2: '2.Regionaler Geschmack nije odgovoran za netočnosti u geografskim podacima, lokacijama proizvođača ili netočnim smjerovima rute.',
            termsS10Title: '§10 Zaštita osobnih podataka',
            termsS10P1: '1. Voditelj obrade primjenjuje tehničke i organizacijske mjere za zaštitu osobnih podataka od gubitka, uništenja ili neovlaštenog pristupa.',
