            termsS6Title: '§6 Nobeiguma noteikumi',
            termsS6Body: 'Piegādātājs patur tiesības grozīt šos noteikumus. Pašreizējā versija vienmēr ir pieejama lietotņu izvēlnē. Jautājumus, kas nav ietverti, regulē Vācijas Federatīvās Republikas tiesību akti.',
            termsS7Title: '§7 Platformas atbildība',
            termsS7P1: '1. Regionaler Geschmack ir platforma, kas savieno lietotājus ar ražotājiem. Tā nav puse nevienā darījumā starp lietotājiem un ražotājiem.',
            termsS7P2Intro: '2. Regionaler Geschmack nav atbildīgs par:',
            termsS7Li1: 'Ražotāju piedāvāto produktu kvalitāte, drošība, autentiskums vai pieejamība',
            termsS7Li2: 'Piegāžu savlaicīgums vai ražotāju pasūtījumu izpilde',
            termsS7Li3: 'Informācijas patiesums preču aprakstos un fotogrāfijās',
            termsS7Li4: 'Ražotāju izturēšanās pret lietotājiem',
            termsS7P3: '3. Lietotāji un ražotāji izmanto platformu uz savu risku. Visi darījumi un līgumi tiek slēgti tieši starp viņiem.',
            termsS8Title: '§8 Ražotāja atbildība par saturu',
            termsS8P1: '1. Ražotāji ir pilnībā atbildīgi par Lietotnē ievietoto saturu (produktu apraksti, fotogrāfijas, cenas, kontaktinformācija).',
            termsS8P2: '2. Regionaler Geschmack nepārbauda ražotāju publicētā satura precizitāti vai likumību.',
            termsS8P3: '3. Ražotāji piekrīt ievērot piemērojamos tiesību aktus, tostarp patērētāju aizsardzības un pārtikas noteikumus.',
            termsS9Title: '§9 Atbildība par ģeogrāfiskajiem datiem',
            termsS9P1: '1. Lietotnē tiek izmantoti ģeogrāfiskie dati no OpenStreetMap (licences ODbL). Precizitāte ir atkarīga no OpenStreetMap kopienas.',
            termsS9P2: '2. Regionaler Geschmack neuzņemas atbildību par neprecizitātēm ģeogrāfiskajos datos, ražotāja atrašanās vietās vai nepareizu maršruta vadību.',
            termsS10Title: '§10 Personas datu aizsardzība',
            termsS10P1: '1. Datu pārzinis piemēro tehniskos un organizatoriskos pasākumus, lai aizsargātu personas datus pret nozaudēšanu, iznīcināšanu vai nesankcionētu piekļuvi.',
            termsS10P2: '2. Lietotājam ir tiesības piekļūt saviem datiem, tos labot, dzēst un pārnest.',
            termsS10P3: '3. Sīkāka informācija par personas datu aizsardzību ir norādīta Lietotnes konfidencialitātes politikā.',
