            termsS9P2: '2. Regionaler Geschmack จะไม่รับผิดชอบต่อความไม่ถูกต้องของข้อมูลทางภูมิศาสตร์ สถานที่ตั้งของผู้ผลิต หรือคำแนะนำเส้นทางที่ไม่ถูกต้อง',
